Here is a basic JavaScript applet that simulates a pendulum and allows the user to input the initial angle and release the pendulum. The applet uses the HTML5 canvas element to render the pendulum and the laws of physics to simulate the swing. Note that this is a simplified model and does not take into account air resistance or other factors that might affect the pendulum's motion.

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Pendulum Simulation</title>
  <style>
    /* Add some basic styling to the applet */
    canvas {
      border: 1px solid black;
    }
  </style>
</head>
<body>
  <h2>Pendulum Simulation</h2>
  <input id="initial-angle" type="number" value="45" required>
  <button id="release-button">Release Pendulum</button>
  <canvas id="pendulum-canvas" width="400" height="400"></canvas>

  <script>
    // Get the canvas element and set its dimensions
    const canvas = document.getElementById('pendulum-canvas');
    const ctx = canvas.getContext('2d');
    canvas.width = 400;
    canvas.height = 400;

    // Define some constants
    const G = 9.81; // acceleration due to gravity (m/s^2)
    const L = 100; // length of the pendulum (pixels)
    const MULT = 100; // multiplier for the pendulum's angle (degrees)

    // Initialize the pendulum's state
    let angle = 0;
    let velocity = 0;

    // Draw the pendulum
    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'black';
      ctx.beginPath();
      ctx.arc(canvas.width / 2, canvas.height / 2, L, angle * MULT, angle * MULT + Math.PI, false);
      ctx.fillStyle = 'blue';
      ctx.fill();
    }

    // Update the pendulum's state
    function update(dt) {
      // Calculate the acceleration due to gravity
      let a = -G * Math.sin(angle * MULT / 180 * Math.PI) / L;

      // Update the velocity and angle
      velocity += a * dt;
      angle += velocity * dt;

      // Keep the angle within bounds (0-360 degrees)
      angle = Math.sin(angle * MULT / 180 * Math.PI + Math.PI / 2) * 180 / Math.PI;
      if (angle > 360) angle -= 360;

      // Check if the pendulum needs to be drawn
      if (angle < 0 || angle > 360) draw();
    }

    // Handle user input and release the pendulum
    document.getElementById('release-button').addEventListener('click', () => {
      angle = parseInt(document.getElementById('initial-angle').value) * MULT / 180 * Math.PI;
      velocity = 0;
      draw();
      setTimeout(() => {
        setInterval(() => {
          update(0.01);
        }, 10);
      }, 1000);
    });

    // Draw the pendulum initially
    draw();

    // Update the pendulum's state at regular intervals
    setInterval(() => {
      update(0.01);
    }, 10);
  </script>
</body>
</html>
