```
package main

import (
	"context"
	"fmt"
	"log"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/ec2"
)

func handler(ctx context.Context) (interface{}, error) {
	sess, err := session.NewSession(&aws.Config{Region: aws.String("your-region")}, nil)
	if err != nil {
		return nil, err
	}

	ec2Svc := ec2.New(sess)

	// Get all EBS snapshots
	input := &ec2.DescribeSnapshotsInput{}
	result, err := ec2Svc.DescribeSnapshots(input)
	if err != nil {
		return nil, err
	}

	for _, snapshot := range result.Snapshots {
		tag := *snapshot.Tags["backup_type"]
		switch {
		case tag == "monthly":
			keep := 14
		case tag == "daily":
			keep := 10
		case tag == "weekly":
			keep := 4
		case tag == "yearly":
			keep := 1
		default:
			log.Printf("Skipping snapshot %s with tag %s", *snapshot.SnapshotId, tag)
			continue
		}

		// Filter out snapshots that are older than the desired keep count
		var filteredSnapshots []*ec2.Snapshot
		for _, s := range result.Snapshots {
			if s.SnapshotId == snapshot.SnapshotId {
				continue
			}
			if *s.Tags["backup_type"] == tag {
				filteredSnapshots = append(filteredSnapshots, s)
			}
		}
		sort.Slice(filteredSnapshots, func(i, j int) bool {
			return aws.Time(*filteredSnapshots[i].StartTime).Before(*aws.Time(*filteredSnapshots[j].StartTime))
		})
		filteredSnapshots = filteredSnapshots[:len(filteredSnapshots)-keep]

		// Delete the extra snapshots
		for _, s := range filteredSnapshots {
		 deletes := &ec2.DeleteSnapshotInput{
				SnapshotId: aws.String(*s.SnapshotId),
			}
			_, err = ec2Svc.DeleteSnapshot(deletes)
			if err != nil {
				return nil, err
			}
			log.Printf("Deleted snapshot %s", *s.SnapshotId)
		}
	}

	return nil, nil
}

func main() {
	lambda.Start(handler)
}
```
