```cpp
#include <iostream>
#include <pigpio.h>

using namespace std;

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Set mode for GPIO pin 12 (set as output)
    gpioSetup(12, PI_OUTPUT);

    // Toggle the state of GPIO pin 12 10 times
    for (int i = 0; i < 10; i++) {
        gpioWrite(12, 1);
        delay(1000);
        gpioWrite(12, 0);
        delay(1000);
    }

    // Reset the state of GPIO pin 12
    gpioWrite(12, 0);

    // Clean up
    gpioTerminate();

    return 0;
}
```

